from scripts.unit1_story_common import zone,cast
META={
'palace_id':'Z2','palace_name':'Chemistry Foyer','story_title':'The Midnight Chemistry Museum',
'tagline':'A glowing carbon token escapes after closing time. Follow it through the museum and watch atoms become the chemistry of life.',
'guide':{'name':'Mina Park','role':'night curator of the chemistry museum','visual':'midnight-blue curator jacket, silver key ring, flashlight that projects electron shells','story_job':'keeps the escaped carbon token in sight and turns each exhibit into a close-up view of how atoms behave'},
'premise':'At midnight, a power surge opens the Living Matter exhibit and releases a glowing carbon token. It rolls through eleven locked galleries, activating each chemistry exhibit in sequence.',
'mission':'Stay with Mina and recover the token. Along the way, identify what matter is made of, how atoms are organized, why electrons govern bonding, and how a few elements become the raw material of biological molecules.',
'finale':'At the Element-Role Workbench, the carbon token clicks back into the Living Matter display beside nitrogen, phosphorus, sulfur, hydrogen, and oxygen. The museum lights return, now showing chemistry as one connected route from atoms to biological molecules.',
'estimated_minutes':17,'checkpoint_indices':[2,6,8],
'route_orientation':'The museum foyer forms a horseshoe around a central atrium. You enter at the Matter Statue, follow the escaped token clockwise through the atomic galleries, cross the bonding bridge, and finish at the biological-element workbench beside the exit.',
'route':[
{'scene_index':0,'locus':'Matter Statue','short':'Matter','floor':'Entrance hall','symbol':'⬢'}, {'scene_index':1,'locus':'Element–Compound Counter','short':'Elements','floor':'Gallery 1','symbol':'▦'}, {'scene_index':2,'locus':'Isotope Scale','short':'Isotopes','floor':'Gallery 2','symbol':'⚖'}, {'scene_index':3,'locus':'Periodic Elevator','short':'Periodic','floor':'Gallery 3','symbol':'▤'}, {'scene_index':4,'locus':'Octopus Valence Chandelier','short':'Valence','floor':'Atrium','symbol':'✳'}, {'scene_index':5,'locus':'Electronegativity Magnet Wall','short':'Attraction','floor':'Gallery 4','symbol':'🧲'}, {'scene_index':6,'locus':'Covalent Tug-of-War Table','short':'Covalent','floor':'Gallery 5','symbol':'↔'}, {'scene_index':7,'locus':'Ion Coat Check','short':'Ions','floor':'Gallery 6','symbol':'+/−'}, {'scene_index':8,'locus':'Hydrogen-Bond Bridge','short':'H bonds','floor':'Bridge','symbol':'···'}, {'scene_index':9,'locus':'Macromolecule Element Crates','short':'Raw atoms','floor':'Bio wing','symbol':'▣'}, {'scene_index':10,'locus':'Element-Role Workbench','short':'Roles','floor':'Exit lab','symbol':'⚙'}]
}
SCENES=[
{'locus':'Matter Statue','title':'The Token Breaks Free','kicker':'Before atoms can matter to life, you need to know what kind of substance you are looking at.','location_description':'You are inside the museum entrance hall. A waist-high bronze statue occupies the center beneath a glass dome. Three labeled pedestals surround it: MATTER, ELEMENT, and COMPOUND.','orientation':'The entrance is behind you. The Matter pedestal is centered, the Element pedestal stands left, and the Compound pedestal stands right. A glowing carbon token has just rolled out from under the dome toward Gallery 1.','zones':[zone('left','Element pedestal','C','Holds one pure kind of atom.'),zone('center','Matter statue','⬢','A heavy bronze form demonstrates that matter occupies space and has mass.'),zone('right','Compound pedestal','H₂O','Locks different elements together in a fixed ratio.')],
'cast':[cast('Matter statue','physical substance','a bronze sphere so heavy it dents its velvet cushion','demonstrates that matter occupies space and has mass'),cast('Element block','pure substance','a single carbon tile that cannot be chemically broken into a simpler substance','represents an element'),cast('Compound model','combined substance','one oxygen-colored sphere fixed to two hydrogen-colored spheres','represents different elements combined in a fixed ratio')],
'paragraphs':['The power drops. The bronze statue shudders, and a coin-sized carbon token slips from its case and skitters across the marble floor. Mina Park catches up beside you, flashlight in hand. “Follow it. Every exhibit it touches wakes up.”','The first pedestal is labeled **matter**. The statue physically occupies space and has measurable mass, which is exactly what matter means. The token ricochets left into a single carbon block. Mina taps it: an **element** is a substance that cannot be broken into other substances by ordinary chemical reactions.','The token then hits a model built from two white spheres and one red sphere locked together. Different elements joined in a fixed ratio form a **compound**. The model is still matter, but now its composition depends on more than one element.','The carbon token shoots beneath the Gallery 1 counter, where the museum keeps track of which elements living organisms need most and which are required only in tiny amounts.']},
{'locus':'Element–Compound Counter','title':'The Living-Matter Inventory','kicker':'Life uses many elements, but not all in the same amounts.','location_description':'Gallery 1 resembles an old apothecary counter. Large glass bins of oxygen, carbon, hydrogen, and nitrogen dominate the center shelves; tiny locked drawers of zinc, copper, iodine, and other elements line the wall.','orientation':'Four enormous CHON bins fill the center. Smaller essential-element bins sit on the left. The trace-element drawers are stacked on the right, one drawer cracked open by the rolling carbon token.','zones':[zone('left','Essential-element shelves','★','Hold elements organisms require for normal life.'),zone('center','CHON bins','96%','Four huge bins visually dominate the living-matter inventory.'),zone('right','Trace drawers','·','Contain elements needed in very small quantities.')],
'cast':[cast('CHON bins','major biological elements','four oversized bins labeled C, H, O, N','show that oxygen, carbon, hydrogen, and nitrogen together make up about 96% of living matter'),cast('Trace drawers','small-quantity requirements','tiny drawers containing elements such as iron, iodine, zinc, and copper','represent trace elements that organisms require in very small amounts')],
'paragraphs':['Mina sweeps her flashlight across the shelves. Only a fraction of naturally occurring elements are **essential elements** for a given organism, meaning the organism needs them to live and function normally. The four giant bins make the main pattern impossible to miss: oxygen, carbon, hydrogen, and nitrogen together account for about 96% of living matter.','The carbon token wedges itself into a tiny drawer. Mina pulls it open with one fingernail. These are **trace elements**: still required, but in very small quantities. “Small amount does not mean unimportant,” she says, returning the token to the counter.','The token escapes again and rolls onto a brass balance in Gallery 2. One side of the scale lights up with protons; the other begins loading neutrons.']},
{'locus':'Isotope Scale','title':'The Number That Names an Element','kicker':'Protons identify the element; neutrons can change the isotope and its mass.','location_description':'A brass scale stands beneath a wall-sized atom. Red proton weights click into the nucleus from the left. Gray neutron weights slide in from the right. An electronic label above the scale changes as the nucleus changes.','orientation':'Proton weights are stacked left, the nucleus and balance occupy center, and neutron/isotope samples sit right. The carbon token rests on the central pan.','zones':[zone('left','Proton rack','+','The proton count determines atomic number and therefore elemental identity.'),zone('center','Isotope scale','⚖','Compares nuclei with the same proton count but different neutron counts.'),zone('right','Mass display','amu','Shows isotope mass and the abundance-weighted atomic mass for a naturally occurring mixture.')],
'cast':[cast('Atomic-number display','identity counter','a red digital counter connected only to proton weights','shows that atomic number equals the number of protons'),cast('Atomic-mass display','mass readout','a scale that can average several isotope masses according to abundance','distinguishes a particular isotope’s mass number from an element’s abundance-weighted atomic mass')],
'paragraphs':['Mina adds six proton weights to the nucleus. The display reads 6. **Atomic number** is the number of protons, and that proton count identifies the element. With six protons, the token remains carbon no matter which common carbon isotope you build.','She leaves the six protons untouched and changes only the number of neutrons. The element is still carbon, but the isotope changes. For one particular isotope, the **mass number** is protons plus neutrons. The **atomic mass** listed for an element with multiple naturally occurring isotopes is different: it is an abundance-weighted average of the isotopic masses.','The scale ejects the carbon token upward into a glass elevator patterned like the periodic table.'] ,'checkpoint_object_id':'MO-APBIO-U1-C006','checkpoint_prompt':'Which atomic property is simply the number of protons and determines an element’s identity?'},
{'locus':'Periodic Elevator','title':'Rows, Columns, and Electron Shells','kicker':'The elevator turns the periodic table into a building you can move through.','location_description':'You stand inside a glass elevator whose walls form a periodic table grid. Vertical columns glow as elevator shafts; horizontal rows become floors. Electron shells appear around each element tile as you travel.','orientation':'Vertical group shafts run along the left and right walls, the elevator car is center, and horizontal period floors extend ahead at each stop.','zones':[zone('left','Group shafts','↓','Elements stacked in a vertical group often share the same number of valence electrons in the simplified main-group model.'),zone('center','Periodic elevator','▤','Carries the carbon token through the grid.'),zone('right','Period floors','→','Elements across the same period have the same number of occupied principal electron shells in the simplified shell model.')],
'cast':[cast('Vertical group','periodic-table relationship','a glowing column of element tiles with matching outer-electron counts','connects similar valence-electron patterns with similar chemical behavior for the main-group elements emphasized here'),cast('Horizontal period','periodic-table relationship','a floor of tiles with the same number of occupied shell rings','connects period number with occupied principal electron shells in the simplified model')],
'paragraphs':['As the elevator rises, Mina points to a vertical shaft. For the main-group elements emphasized in introductory biology, elements in the same **group** generally share the same number of valence electrons and therefore often show similar chemical behavior. The matching outer electrons glow around each tile in the column.','The elevator stops on a horizontal floor. Every tile across that **period** shows the same number of occupied principal electron shells in the simplified shell model, even though the outer electrons differ as you move across the row.','The escaped token bounces off carbon’s tile and drops through the elevator ceiling into the atrium, where an eight-armed chandelier is opening above you.']},
{'locus':'Octopus Valence Chandelier','title':'The Outer Shell Takes Control','kicker':'The electrons farthest from the nucleus are the ones that usually decide how atoms interact.','location_description':'In the central atrium hangs a kinetic chandelier shaped like an eight-armed octopus. Transparent electron shells circle its body. Only the outermost ring connects to the moving arms.','orientation':'The chandelier hangs overhead at center. A shell projector stands left, and eight empty or occupied arm sockets form a bright ring on the right side of the display.','zones':[zone('left','Shell projector','◎','Shows inner shells as stable rings and highlights the outermost occupied shell.'),zone('center','Valence chandelier','✳','The outer shell controls the bonding arms.'),zone('right','Eight-arm frame','8','Demonstrates the octet heuristic without pretending it is a universal law.')],
'cast':[cast('Valence shell','outer electron shell','the outermost glowing ring around the chandelier','contains the electrons most directly involved in many chemical interactions'),cast('Octet frame','stability heuristic','an eight-socket ring that becomes especially stable when filled for many main-group atoms','represents the useful octet rule heuristic while reminding learners that chemistry has exceptions')],
'paragraphs':['Mina dims every inner ring and leaves only the outermost occupied shell glowing. That is the **valence shell**. Its electrons are the ones most directly involved when many atoms form chemical bonds.','The chandelier’s eight sockets illuminate. For many main-group atoms, bonding can produce a more stable arrangement with eight electrons in the valence shell. This is the **octet rule**, a useful heuristic, not a universal command. Atoms do not “want” electrons; the rule summarizes common stable electron arrangements.','The carbon token grabs four of the chandelier arms, then tears loose and flies toward a wall covered in giant magnetic element tiles.']},
{'locus':'Electronegativity Magnet Wall','title':'Who Pulls the Electrons Harder?','kicker':'A bond can be shared while the electrons still spend more time near one atom.','location_description':'Gallery 4 is dominated by a magnetic wall. Two atom tiles can clamp together while a glowing electron cloud stretches between them. Some tiles tug the shared cloud much harder than others.','orientation':'A periodic-table gradient runs left to right across the back wall, the shared-electron display sits center, and a bond clamp is mounted to the right.','zones':[zone('left','Electronegativity gradient','↗','The pull generally strengthens across a period and weakens down a group in the main-group region emphasized here.'),zone('center','Electron cloud','☁','Shows where shared electrons spend more time.'),zone('right','Bond clamp','—','Holds atoms or ions together through attraction.')],
'cast':[cast('Electronegativity','electron-pulling tendency','a magnet-strength meter attached to each atom tile','measures an atom’s ability to attract electrons toward itself'),cast('Chemical bond','attractive connection','a clamp that can hold atoms or ions together','represents attraction that holds atoms or ions together, including covalent and ionic bonding')],
'paragraphs':['Mina locks hydrogen and oxygen tiles into the bond clamp. A **chemical bond** is an attraction that holds atoms or ions together. Here the glowing electron cloud is shared, but it shifts toward oxygen because the two atoms do not pull equally.','The strength of that pull is **electronegativity**: an atom’s ability to attract electrons toward itself. On the wall, the general trend climbs from left to right across a period and falls as you move down a group in the main-group region you are using.','The carbon token hits the cloud and sends it sliding into the next gallery, where two mechanical arms are already gripping the same glowing rope.']},
{'locus':'Covalent Tug-of-War Table','title':'Shared Does Not Always Mean Equal','kicker':'Covalent bonds are shared electron pairs; polarity depends on how evenly they are shared.','location_description':'A long table is painted like a tug-of-war court. Atom models stand at opposite ends gripping glowing electron-pair ropes. A balance meter above each rope shows whether the sharing is equal or unequal.','orientation':'Equal-pull atoms occupy the left lane, the main tug-of-war table is center, and an unequal-pull oxygen–hydrogen pair occupies the right lane.','zones':[zone('left','Equal-pull lane','↔','The shared electron pair stays centered.'),zone('center','Covalent table','—','Single, double, and triple ropes represent one, two, or three shared electron pairs.'),zone('right','Unequal-pull lane','δ','The shared electron cloud shifts toward the more electronegative atom, creating partial charges.')],
'cast':[cast('Covalent bond','shared-electron bond','one or more glowing ropes shared between two atoms','forms when atoms share electron pairs'),cast('Nonpolar covalent bond','equal sharing','a rope centered evenly between equal pullers','shares electrons approximately equally'),cast('Polar covalent bond','unequal sharing','a rope pulled off-center toward the stronger atom','shares electrons unequally and produces partial charges')],
'paragraphs':['At the center table, two atoms grip the same electron-pair rope. A **covalent bond** forms when atoms share electron pairs. One rope represents a single bond, two shared pairs a double bond, and three shared pairs a triple bond.','In the left lane, the pull is balanced. The shared electrons remain centered: a **nonpolar covalent bond**. In the right lane, oxygen pulls the shared cloud toward itself. The electrons are still shared, but unequally. That is a **polar covalent bond**, and the unequal sharing creates partial charges rather than full ionic charges.','The carbon token slices the rope loose. One atom model loses an electron prop while another gains it, and both are sucked through the doors of the Ion Coat Check.'] ,'checkpoint_object_id':'MO-APBIO-U1-C017','checkpoint_prompt':'What kind of covalent bond shares electrons unequally and produces partial charges?'},
{'locus':'Ion Coat Check','title':'Full Charges at the Coat Check','kicker':'Electron transfer can create ions; the ionic bond is the attraction between the resulting opposite charges.','location_description':'Gallery 6 resembles a coat check with two counters. Electron-shaped coat tokens are handed from one atom model to another. Large + and − badges light up only after the transfer.','orientation':'The electron-return counter is left, the ion badge gate is center, and the opposite-charge attraction rail is right.','zones':[zone('left','Electron transfer counter','e⁻','Creates charged particles when atoms gain or lose electrons.'),zone('center','Charge badge gate','+/−','Assigns full positive or negative ionic charge.'),zone('right','Attraction rail','⇆','Pulls oppositely charged ions together.')],
'cast':[cast('Cation','positive ion','an atom model wearing a bright + badge after losing electron density','is a positively charged ion'),cast('Anion','negative ion','an atom model wearing a bright − badge after gaining electron density','is a negatively charged ion'),cast('Ionic bond','electrostatic attraction','a rail that snaps the + and − ions toward one another','is the electrostatic attraction between oppositely charged ions, not the electron-transfer event itself')],
'paragraphs':['One atom leaves an electron token behind and exits with a full positive badge. A positively charged ion is a **cation**. Another atom picks up the electron and receives a full negative badge. A negatively charged ion is an **anion**.','The important event comes next. The + and − models are pulled toward one another by electrostatic attraction. That attraction is the **ionic bond**. Electron transfer can create the ions, but the transfer itself is not the bond.','The opposite charges snap together hard enough to launch the carbon token onto a narrow bridge where partial charges, not full ionic charges, are reaching across dotted lines.']},
{'locus':'Hydrogen-Bond Bridge','title':'The Dotted Bridges That Never Stay Still','kicker':'A hydrogen bond is weaker than a covalent bond but powerful when many act together.','location_description':'A suspended glass bridge crosses the museum atrium. Water molecules drift beneath its floor. Solid O–H links hold each molecule together while dotted lines appear and disappear between neighboring molecules.','orientation':'One enlarged water molecule floats left, the bridge itself crosses center, and a moving crowd of water molecules fills the right-side projection.','zones':[zone('left','Covalent O–H bonds','—','Solid links hold oxygen and hydrogen together inside each water molecule.'),zone('center','Hydrogen-bond span','···','A dotted attraction forms between a partially positive hydrogen and an electronegative atom on a nearby partner.'),zone('right','Liquid-water crowd','≈','Dotted hydrogen bonds continually form, break, and reform as molecules move.')],
'cast':[cast('Hydrogen bond','noncovalent attraction','a dotted bridge from a partially positive H toward an electronegative atom','links suitable partial charges between molecules or within large molecules without becoming the covalent bond inside the molecule'),cast('Moving water molecules','dynamic network','a crowd whose dotted connections flicker on and off','shows that liquid-water hydrogen bonds continually form, break, and reform')],
'paragraphs':['Mina freezes one enlarged water molecule in the air. Its O–H links are solid covalent bonds. A neighboring molecule approaches, and a dotted line appears between a partially positive hydrogen and the electronegative oxygen of the neighbor. That dotted attraction is a **hydrogen bond**.', 'Hydrogen bonds are noncovalent attractions. They can form between separate molecules or between suitable groups within large biological molecules. In liquid water they are not permanent struts: the dotted connections continually **form, break, and reform** as the molecules move.', 'The carbon token runs across the flickering dotted bridge and lands inside a shipping crate stamped FROM ENVIRONMENT. Mina follows it into the biological-materials wing.'] ,'checkpoint_object_id':'MO-APBIO-U1-C021','checkpoint_prompt':'What noncovalent attraction forms between a partially positive hydrogen and another electronegative atom?'},
{'locus':'Macromolecule Element Crates','title':'The Atoms Life Has to Import','kicker':'Cells cannot build biological molecules without matter from the environment.','location_description':'The bio wing looks like a loading dock. Crates of carbon dioxide, water, minerals, and nutrients arrive through a rolling door. Conveyor belts feed their atoms toward models of carbohydrates, proteins, lipids, and nucleic acids.','orientation':'Incoming environmental crates line the left wall, sorting conveyors fill center, and four macromolecule assembly bins wait on the right.','zones':[zone('left','Environmental deliveries','↓','Bring atoms and molecules into the system.'),zone('center','Atom-sorting conveyor','C H O','Separates useful atoms from incoming substances.'),zone('right','Biomolecule bins','4','Receive atoms used to build carbohydrates, proteins, lipids, and nucleic acids.')],
'cast':[cast('Environmental matter','raw material','crates of gases, water, ions, and nutrients','supplies the atoms and molecules organisms need to build new biological material'),cast('C/H/O stream','common building atoms','three brightly labeled conveyor lanes','shows the widespread use of carbon, hydrogen, and oxygen across major biological molecules')],
'paragraphs':['A cell cannot manufacture carbon atoms from nothing. The loading dock makes that limitation concrete: **atoms and molecules from the environment** provide the matter organisms use to grow, repair, reproduce, and build new molecules.', 'Three conveyor lanes—carbon, hydrogen, and oxygen—feed repeatedly into models of carbohydrates, proteins, lipids, and nucleic acids. Those elements are especially prevalent across the biological molecules you will study.', 'The carbon token finally slows beside a workbench where nitrogen, phosphorus, and sulfur tools are waiting for more specialized jobs.']},
{'locus':'Element-Role Workbench','title':'Different Elements, Different Jobs','kicker':'The final workbench ties elemental identity to the structures cells actually build.','location_description':'At the exit lab, a large molecular workbench is divided into three stations: sulfur tools on the left, phosphorus tools in the middle, and nitrogen tools on the right. The escaped carbon token rests in an empty slot at the front.','orientation':'Sulfur is left, phosphorus center, nitrogen right, and the carbon-token slot sits directly in front of you.','zones':[zone('left','Sulfur station','S','Shows sulfur entering selected amino-acid side chains and some proteins.'),zone('center','Phosphorus station','P','Feeds phosphate groups into nucleic acids and phospholipid heads.'),zone('right','Nitrogen station','N','Feeds nitrogen into amino acids/proteins and nitrogenous bases in nucleic acids.')],
'cast':[cast('Sulfur','biological element','yellow atom tags clipped to selected amino-acid side chains','occurs in some amino acids and therefore some proteins, but not every protein'),cast('Phosphorus','biological element','phosphate tags moving toward DNA backbones and phospholipid heads','contributes to nucleic acids and phospholipids through phosphate groups'),cast('Nitrogen','biological element','blue atom tags entering amino groups and nitrogenous bases','is part of amino acids/proteins and nucleic-acid bases')],
'paragraphs':['Mina picks up the sulfur tool first. **Sulfur** occurs in some amino acids, including cysteine and methionine, so it appears in some proteins but is not an invariant ingredient of every protein.', '**Phosphorus** moves down the center track as phosphate groups. You see it enter nucleic-acid sugar-phosphate backbones and the phosphate-containing head region of phospholipids.', 'On the right, **nitrogen** enters amino-acid amino groups and protein backbones, then appears again in the nitrogenous bases of nucleic acids. The same element can therefore support different structures in different molecules.', 'Mina presses the escaped carbon token into the empty slot. The museum lights climb back on gallery by gallery: matter, elements, atomic structure, electron shells, bonding, and biological element roles now form one continuous route.']}
]
